    fun byId(id: Long): HealthStructure? = all.firstOrNull { it.id == id }

    fun mergeWith(remote: List<HealthStructure>): List<HealthStructure> {
        if (remote.isEmpty()) return all
        val localNames = all.map { it.displayName.lowercase() }.toSet()
        val extras = remote.filter { it.displayName.lowercase() !in localNames }
        return all + extras
    }

    private fun center(
        id: Long,
        name: String,
        province: String,
        city: String,
        address: String,
        lat: Double,
        lon: Double,
        phone: String?,
        type: String,
        services: String,
        photo: String?,
    ) = HealthStructure(
        id = id,
        name = name,
        nom = name,
        province = province,
        city = city,
        ville = city,
        address = address,
        adresse = address,
        latitude = lat,
        longitude = lon,
        phone = phone,
        email = null,
        services = services,
        structureType = type,
        openingHours = "Horaires non renseignés",
        photoUrl = photo,
        status = "active",
    )
}
